import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"With an agent","description":"","frontmatter":{"title":"With an agent"},"headers":[],"relativePath":"en/agent/index.md","filePath":"en/agent/index.md"}'),r={name:"en/agent/index.md"};function h(s,e,i,d,c,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="with-an-agent" tabindex="-1">With an agent <a class="header-anchor" href="#with-an-agent" aria-label="Permalink to &quot;With an agent&quot;">​</a></h1><p>An agent connected to Kessho is an AI assistant (Claude Code, Codex, Gemini CLI… see <a href="/en/agent/connecter.html">Connect the agent</a>) that talks to your memory through Kessho&#39;s MCP server. It reads what you have already decided, writes what the session brings, and you find it on screen: the application and the agent look at the <strong>same folder</strong> of notes (see <a href="/en/guide/vault.html">Choosing your memory</a>).</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>An assistant has no memory from one session to the next, nor from one tool to another. With Kessho, what matters is written into your memory, a folder of Markdown notes that is yours: the next session, in the same assistant or another one, starts from there without you having to say it all again.</p><h2 id="the-cycle-resume-work-archive" tabindex="-1">The cycle: resume, work, archive <a class="header-anchor" href="#the-cycle-resume-work-archive" aria-label="Permalink to &quot;The cycle: resume, work, archive&quot;">​</a></h2><ol><li><strong>Resume.</strong> You say &quot;let&#39;s pick up project X&quot;; the agent loads that project&#39;s context. See <a href="/en/agent/reprendre.html">Resume a project</a>.</li><li><strong>Work.</strong> During the session, the agent can search, note a decision, tidy up. See <a href="/en/agent/chercher.html">Search the memory</a> and <a href="/en/agent/ecrire.html">Write to the memory</a>.</li><li><strong>Archive.</strong> At the end of the session, the agent writes a dated archive and updates the project&#39;s context. See <a href="/en/agent/archiver.html">Archive a session</a>.</li></ol><h2 id="who-does-what" tabindex="-1">Who does what <a class="header-anchor" href="#who-does-what" aria-label="Permalink to &quot;Who does what&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>What it does</th><th>Where you see it</th></tr></thead><tbody><tr><td><strong>The application</strong> (Kessho)</td><td>Declares its server in your assistants, drops the procedures that tell them when to call it, displays the memory, syncs it in one click.</td><td>The screens of the <a href="/en/guide/">application guide</a>.</td></tr><tr><td><strong>The agent</strong></td><td>Calls the MCP tools (the <code>mem_*</code> ones): read, search, write, tidy up. Each tool is described in the <a href="/en/reference/mcp/">MCP reference</a>.</td><td>The freshness indicator lights up when it writes (see <a href="/en/guide/zones.html">Zones</a>).</td></tr></tbody></table><p>Every page of this section starts from what you say to the agent, then explains what the agent does (the tools it calls, what changes in the memory), then what the application shows.</p><h2 id="the-seven-journeys" tabindex="-1">The seven journeys <a class="header-anchor" href="#the-seven-journeys" aria-label="Permalink to &quot;The seven journeys&quot;">​</a></h2><ul><li><a href="/en/agent/connecter.html">Connect the agent</a>: connect your assistant, and check that it sees Kessho.</li><li><a href="/en/agent/reprendre.html">Resume a project</a>: find where you left off, without re-explaining anything.</li><li><a href="/en/agent/archiver.html">Archive a session</a>: keep a trace of a session, and undo it if needed.</li><li><a href="/en/agent/chercher.html">Search the memory</a>: find a decision, a file, a note.</li><li><a href="/en/agent/ecrire.html">Write to the memory</a>: note a fact, a principle, a goal, a person, a document.</li><li><a href="/en/agent/entretenir.html">Maintain the memory</a>: check the folder&#39;s health, rename, move, remove.</li><li><a href="/en/agent/synchroniser.html">Sync the memory</a>: keep the memory up to date across your machines, with git.</li></ul><p>The complete list of tools, with their parameters, is in the <a href="/en/reference/mcp/">MCP reference</a>.</p><h2 id="an-agent-does-not-do-everything-on-its-own" tabindex="-1">An agent does not do everything on its own <a class="header-anchor" href="#an-agent-does-not-do-everything-on-its-own" aria-label="Permalink to &quot;An agent does not do everything on its own&quot;">​</a></h2><p>Some tools only run under a condition, which each journey recalls: a dry run before applying (<code>apply</code>, <code>confirm</code>), a justified confirmation to remove a note. These safeguards are the server&#39;s, not the agent&#39;s good manners.</p><p>Another kind of instruction is not checked by the server: for <code>mem_git_commit</code> and <code>mem_git_resolve</code>, it is the tool&#39;s description that tells the agent to obtain the user&#39;s agreement; the server does not verify it.</p>',15)])])}const u=t(r,[["render",h]]);export{g as __pageData,u as default};
